  stem = excluded.stem,
  choices = excluded.choices,
  answer_index = excluded.answer_index,
  explanation = excluded.explanation,
  lifecycle = excluded.lifecycle,
  is_playable = excluded.is_playable,
  source_path = excluded.source_path,
  updated_at = now();

insert into public.questions (
  id, subject, chapter, chapter_title, topic, canonical_topic, subtopic,
  pass_number, difficulty, stem, choices, answer_index, explanation,
  lifecycle, is_playable, source_path, updated_at
) values
  ('adsp-r48-3-32', 'adsp', 3, '데이터 분석', '주성분 분석(PCA)', '주성분 분석(PCA)', '주성분의 설명 분산', 1, 3, '다음은 주성분 분석(PCA)에 대한 설명이다. 이 중 옳지 않은 것은 무엇인가?', '["제1주성분에서 제2주성분으로 갈수록 각 주성분이 설명하는 분산은 증가한다.","주성분 분석은 다변량 데이터를 저차원으로 축소하는 기법이다.","주성분은 서로 직교(orthogonal)한다.","주성분의 개수는 원래 변수의 개수 이하이다."]'::jsonb, 0, '"주성분은 설명 분산(고유값)이 큰 순서대로 추출되므로 1st > 2nd > 3rd … 로 감소. ''증가''는 틀림."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-33', 'adsp', 3, '데이터 분석', '다중 선형회귀', '다중 선형회귀', '변수 유의성 해석', 1, 4, '다중 선형회귀분석 결과를 해석할 때 옳지 않은 것은 무엇인가?', '["회귀계수의 절댓값이 가장 큰 변수가 자동으로 가장 유의한 변수가 된다.","결정계수(R²)가 1 에 가까울수록 모형의 설명력이 높다.","각 설명변수의 p-value 로 통계적 유의성을 판단할 수 있다.","F-통계량을 통해 모형 전체의 유의성을 검정할 수 있다."]'::jsonb, 0, '"회귀계수의 크기는 변수의 단위·스케일에 따라 달라지므로 ''계수가 큰 변수 = 가장 유의''는 성립하지 않는다. 통계적 유의성은 t값·p-value 로 판단해야 한다."'::jsonb, 'self-reviewed', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-34', 'adsp', 3, '데이터 분석', '로지스틱 회귀', '로지스틱 회귀', '연결함수(link function)', 1, 3, '다음은 로지스틱 회귀분석(Logistic Regression)에 대한 설명이다. 이 중 가장 적절하지 않은 것은 무엇인가?', '["로지스틱 회귀의 연결함수는 시그모이드 함수이다.","로지스틱 회귀는 이항 분류 문제에 적용할 수 있다.","오즈비(odds ratio)로 계수의 효과를 해석할 수 있다.","최우추정법(MLE)을 통해 계수를 추정한다."]'::jsonb, 0, '"로지스틱 회귀의 연결함수는 ''로짓(logit) 함수'' = ln(p/(1-p)). 시그모이드는 로짓의 역함수(반응함수)로 확률 변환에 쓰이지만 link function 은 아니다."'::jsonb, 'self-reviewed', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-35', 'adsp', 3, '데이터 분석', '상관계수', '상관계수', '음의 상관관계 해석', 1, 3, '다음은 두 개의 숫자형 변수 간의 관계를 파악하기 위한 척도에 대한 설명이다. 이 중 가장 적절하지 않은 것은 무엇인가?', '["상관계수의 부호가 음수이면, 두 변수는 반비례 관계라고 해석할 수 있다.","피어슨 상관계수는 두 변수의 선형관계를 측정한다.","공분산의 값은 변수의 단위에 따라 크기가 달라진다.","스피어만 상관계수는 순위 기반으로 단조(비선형) 관계도 측정할 수 있다."]'::jsonb, 0, '"음의 상관계수는 ''음의 선형관계''를 의미할 뿐 반비례(y = k/x)와 다르다. 반비례는 특정한 비선형 함수 관계."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-36', 'adsp', 3, '데이터 분석', '시계열 분해', '시계열 분해', '구성 요소', 1, 2, '다음 중 분해 시계열(decomposition time series)을 구성하는 요소로 적절하지 않은 것은 무엇인가?', '["규칙요인","추세요인(Trend)","계절요인(Seasonal)","불규칙요인(Irregular)"]'::jsonb, 0, '"분해 시계열 = 추세 + 순환 + 계절 + 불규칙 요인. ''규칙요인''이라는 공식 구성 요소는 없다."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-37', 'adsp', 3, '데이터 분석', '단순 선형회귀', '단순 선형회귀', '절편 유의성 판단', 1, 4, '단순 선형회귀분석 결과를 해석할 때 옳지 않은 것은 무엇인가?', '["회귀식의 절편이 통계적으로 유의한지 여부는 회귀 결과표만으로는 알 수 없다.","설명변수 계수의 p-value 가 유의수준보다 작으면 통계적으로 유의한 설명변수이다.","결정계수는 모형이 종속변수의 분산을 설명하는 비율을 나타낸다.","회귀계수 추정치의 부호가 양수이면 설명변수 증가에 따라 종속변수가 증가한다고 해석할 수 있다."]'::jsonb, 0, '"절편(Intercept)의 유의성은 회귀 결과표의 Intercept 행 p-value 로 확인 가능. ''알 수 없다''는 틀림."'::jsonb, 'self-reviewed', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-38', 'adsp', 3, '데이터 분석', '정상 시계열', '정상 시계열', '추세 제거 변환', 1, 2, '다음 중 추세가 존재하는 비정상 시계열을 정상 시계열로 변환하는 방법으로 가장 적절한 것은 무엇인가?', '["차분","이동평균","지수평활","주파수 변환"]'::jsonb, 0, '"추세 제거 = 차분(differencing). 계절성 제거 = 계절차분. 분산 안정화 = 로그 변환."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-39', 'adsp', 3, '데이터 분석', '데이터 분할', '데이터 분할', '학습·검증·테스트 용도', 1, 3, '다음은 데이터 분할(학습·검증·테스트 데이터)에 대한 설명이다. 이 중 옳지 않은 것은 무엇인가?', '["검증 데이터는 최종 모델의 성능을 평가하기 위해 사용된다.","학습 데이터는 모델의 파라미터를 추정하는 데 사용된다.","테스트 데이터는 모델 학습 과정에 절대 사용되지 않는다.","교차검증은 학습/검증 데이터 분할의 무작위성을 보완한다."]'::jsonb, 0, '"최종 모델 성능 평가는 ''테스트 데이터''. 검증 데이터는 하이퍼파라미터 튜닝·모델 선택을 위한 중간 평가용."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-40', 'adsp', 3, '데이터 분석', '데이터 마이닝 프로세스', '데이터 마이닝 프로세스', '추진 단계 순서', 1, 3, '아래 데이터 마이닝 추진 단계를 순서대로 나열한 것 중 가장 옳은 것은?
(가) 데이터 준비
(나) 목적 정의
(다) 데이터 마이닝 기법 적용
(라) 데이터 가공
(마) 검증', '["(나) → (가) → (라) → (다) → (마)","(가) → (나) → (라) → (다) → (마)","(나) → (라) → (가) → (다) → (마)","(가) → (나) → (다) → (라) → (마)"]'::jsonb, 0, '"데이터 마이닝 5단계: 목적 정의 → 데이터 준비 → 데이터 가공 → 기법 적용 → 검증."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-41', 'adsp', 3, '데이터 분석', '의사결정나무', '의사결정나무', '회귀 트리 예측 정확도', 1, 3, '다음은 의사결정나무 모형에 대한 설명이다. 이 중 가장 적절하지 않은 것은 무엇인가?', '["회귀 트리는 학습 데이터에서 항상 예측 정확도 100% 를 보장한다.","의사결정나무는 범주형·연속형 변수 모두 처리할 수 있다.","가지치기(pruning)는 과적합을 방지하기 위한 방법이다.","분류 기준으로 지니 지수, 엔트로피 등이 사용된다."]'::jsonb, 0, '"회귀 트리는 잎 노드에 속한 샘플들의 평균으로 예측한다. 잎이 단일 샘플이 아닌 이상 학습 데이터에서도 100% 예측은 불가능 — ''항상''이라는 보편 양화는 틀림."'::jsonb, 'self-reviewed', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-42', 'adsp', 3, '데이터 분석', '인공신경망', '인공신경망', '활성화 함수', 1, 2, '인공신경망 모형에서 입력층에서 전달된 신호의 합을 출력값으로 변환하여 다음 층으로 전달하는 함수는 무엇인가?', '["활성화 함수","손실 함수","최적화 함수","정규화 함수"]'::jsonb, 0, '"활성화 함수(activation function) = 가중합을 비선형 출력으로 변환하여 다음 층으로 전달. 예: 시그모이드, tanh, ReLU."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-43', 'adsp', 3, '데이터 분석', '거리 측도', '거리 측도', '마할라노비스 거리', 1, 2, '다음 중 변수 간 상관관계를 고려하여 거리 측정을 수행하는 방법은 무엇인가?', '["마할라노비스 거리","유클리디언 거리","맨하탄 거리","민코프스키 거리"]'::jsonb, 0, '"마할라노비스 거리는 공분산 행렬의 역행렬을 이용해 변수 간 상관구조를 반영. 유클리디언·맨하탄·민코프스키는 단순 좌표 기반 거리."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-44', 'adsp', 3, '데이터 분석', '분류 평가 지표', '분류 평가 지표', 'F1-score', 1, 2, '아래 설명이 나타내는 평가 지표는 무엇인가?
정밀도(precision)와 재현율(recall)은 한 지표의 값이 높아지면 다른 지표의 값이 낮아질 가능성이 높은 관계를 지니고 있다. (      )는 이러한 효과를 보정하기 위해 만든 지표이다.', '["F1-score","정확도(Accuracy)","AUC","특이도(Specificity)"]'::jsonb, 0, '"F1-score = 2·(Precision·Recall)/(Precision+Recall) = 정밀도와 재현율의 조화평균. 두 지표의 trade-off 를 균형 있게 반영."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-45', 'adsp', 3, '데이터 분석', '연관규칙', '연관규칙', '지지도 계산식', 1, 2, '연관규칙 A→B 에 대한 지지도(support)의 계산식으로 올바른 것은 무엇인가?', '["(A 와 B 가 동시에 포함된 거래 수) / (전체 거래 수)","(A 와 B 가 동시에 포함된 거래 수) / (A 를 포함한 거래 수)","(A 와 B 가 동시에 포함된 거래 수) / (B 를 포함한 거래 수)","P(B|A) / P(B)"]'::jsonb, 0, '"지지도 Support(A→B) = P(A ∩ B). 신뢰도 = P(B|A). 향상도 = P(B|A)/P(B)."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-46', 'adsp', 3, '데이터 분석', '결측값 처리', '결측값 처리', '삭제 확률 계산', 1, 3, '이름과 성별로 구성된 고객 데이터가 있다. 각 고객 데이터에서 이름 항목과 성별 항목은 각각 10% 의 확률로 결측값을 가진다고 하자. 이름과 성별의 결측 여부는 서로 독립적이며, 이름 또는 성별 중 하나라도 결측값이 존재하는 고객 데이터는 모두 삭제된다. 이때, 임의로 하나의 고객 데이터를 선택했을 때 해당 데이터가 삭제될 확률은 얼마인가?', '["19%","10%","20%","1%"]'::jsonb, 0, '"삭제될 확률 = 1 − P(두 항목 모두 결측 아님) = 1 − (0.9 × 0.9) = 1 − 0.81 = 0.19 → 19%."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-47', 'adsp', 3, '데이터 분석', '군집분석', '군집분석', '와드 연결법', 1, 2, '다음 중 군집 내 오차 제곱합(SSE)의 증가량을 최소화하는 군집분석 연결법은 무엇인가?', '["와드 연결법(Ward''s method)","단일 연결법(최단거리법)","완전 연결법(최장거리법)","평균 연결법"]'::jsonb, 0, '"Ward''s method 는 두 군집을 병합했을 때 발생하는 군집 내 SSE 증가량이 최소가 되도록 병합 쌍을 선택한다."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-48', 'adsp', 3, '데이터 분석', '비지도 학습', '비지도 학습', 'K-평균 군집분석', 1, 2, '정형데이터마이닝 기법 중 반응변수(종속변수)가 없는 데이터의 구조를 파악하는 데 활용되는 기법은 무엇인가?', '["K-평균 군집분석","로지스틱 회귀","의사결정나무","선형 회귀"]'::jsonb, 0, '"반응변수(y)가 없는 데이터 = 비지도 학습. 대표 기법 = 군집분석(K-means), 연관규칙, PCA 등."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-49', 'adsp', 3, '데이터 분석', '연관규칙', '연관규칙', '신뢰도 계산', 1, 3, '아래 거래에서 연관규칙 A→B 의 신뢰도(Confidence)는 얼마인가?
품목           거래 건수
[A]                100
[B, D]             100
[C]                100
[A, B, C, D]    50
[B, D]            200
[A, B, D]       250
[A, C]           200', '["50%","33%","25%","60%"]'::jsonb, 0, '"전체 거래 = 1000. A 를 포함한 거래 = 100+50+250+200 = 600. A 와 B 동시 포함 = 50+250 = 300. Confidence(A→B) = 300/600 = 50%."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-r48-3-50', 'adsp', 3, '데이터 분석', '연관규칙', '연관규칙', '향상도(Lift) 해석', 1, 2, '연관규칙에서 향상도(Lift)에 대한 설명으로 가장 적절한 것은?', '["향상도가 1 보다 크면 해당 규칙은 의미 있는 연관성을 가진다고 볼 수 있다.","향상도는 지지도(support)와 같은 범위를 가진다.","향상도가 0 에 가까우면 강한 양의 연관성을 의미한다.","향상도는 항상 0 과 1 사이의 값을 가진다."]'::jsonb, 0, '"Lift = P(B|A) / P(B). Lift = 1: 독립. Lift > 1: 양의 연관(의미 있음). Lift < 1: 음의 연관. 값의 범위는 0 이상의 실수(상한 없음)."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/past-exams/2026-48.json', now()),
  ('adsp-3-sample-001', 'adsp', 3, '데이터 분석', '통계적 가설 검정', '통계적 가설 검정', null, 1, 3, '유의수준 0.05 하에서 다음 중 귀무가설을 기각할 수 있는 경우는?', '["p-value = 0.08","p-value = 0.03","p-value = 0.50","p-value = 0.10"]'::jsonb, 1, '"p-value 가 유의수준 α=0.05 보다 작을 때 귀무가설을 기각합니다."'::jsonb, 'ai-generated', true, 'src/data/questions/adsp/sample.json', now()),
  ('sqld-1-1-cp-01', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', null, 1, 1, '데이터 모델링의 3가지 특징("단추명")으로 옳지 않은 것은?', '["단순화","추상화","명확화","정형화"]'::jsonb, 3, '"모델링의 3특징은 단순화·추상화·명확화 (\"단추명\"). 정형화는 별개 개념입니다."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-1-cp-02', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', null, 1, 2, '데이터 모델링 단계의 순서로 옳은 것은?', '["물리적 → 논리적 → 개념적","개념적 → 물리적 → 논리적","개념적 → 논리적 → 물리적","논리적 → 개념적 → 물리적"]'::jsonb, 2, '"개념적 → 논리적 → 물리적 (\"개논물\"). 아래로 갈수록 추상화 ↓ 구체화 ↑. 논리적 단계가 재사용성 가장 높음."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-1-cp-03', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', null, 1, 2, '다음 설명에 해당하는 스키마 구조로 가장 적절한 것은?

[설명] 모든 사용자 관점을 통합한 조직 전체 관점의 통합적 표현', '["외부 스키마","개념 스키마","내부 스키마","응용 스키마"]'::jsonb, 1, '"ANSI/SPARC 3계층 — 외부(사용자별 뷰) · 개념(전체 통합) · 내부(물리 저장). \"통합적 표현\" 키워드는 개념 스키마. \"응용 스키마\"는 가짜 보기."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-1-cp-04', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', null, 1, 2, '엔터티가 갖춰야 할 특성으로 옳지 않은 것은?', '["업무에서 필요한 정보여야 한다","유일하게 식별되어야 한다","반드시 영속적으로 저장되어야 한다","2개 이상의 인스턴스를 가져야 한다"]'::jsonb, 2, '"엔터티 5요건은 업무 필요·식별성·2개 이상 인스턴스·속성 보유·관계 필수. \"영속적 저장\"은 조건이 아닙니다 (임시 엔터티도 가능)."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-1-cp-05', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', null, 1, 2, '엔터티의 발생 시점에 따른 분류가 아닌 것은?', '["기본 엔터티","중심 엔터티","관계 엔터티","행위 엔터티"]'::jsonb, 2, '"발생 시점 분류는 기본·중심·행위 (3가지뿐). \"관계 엔터티\"는 분류명에 없습니다 (가짜 보기). 유무형 분류는 유형·개념·사건 (\"개사유\")."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-1-cp-06', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', null, 1, 2, '다른 속성으로부터 계산이나 변형으로 생성되는 속성은?', '["기본 속성","설계 속성","일반 속성","파생 속성"]'::jsonb, 3, '"기본=업무에 원래 존재, 설계=설계 시 새로 정의, 파생=계산·변형으로 생성. 합계, 평균, 나이(생년월일에서 계산) 등이 파생 속성."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-1-cp-07', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', null, 1, 2, '관계의 구성요소("관차선")가 아닌 것은?', '["관계명","차수","선택사양","연결성"]'::jsonb, 3, '"관계 구성은 관계명(Membership) · 차수(Cardinality) · 선택사양(Optionality) — \"관차선\". \"연결성\"은 별개 보기."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-1-cp-08', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', null, 1, 3, '주식별자에 관한 설명 중 옳지 않은 것은?', '["각 인스턴스를 유일하게 식별할 수 있어야 한다","주식별자 값은 NULL이어도 된다","값이 자주 변하지 않아야 한다","유일성을 만족하는 선에서 최소한의 속성으로 구성한다"]'::jsonb, 1, '"주식별자 4요건 — 유일성·최소성·불변성·존재성(NOT NULL). NULL 절대 허용 X. 의미성도 요건이 아닙니다."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-1-cp-09', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', null, 1, 3, '식별자 관계와 비식별자 관계에 관한 설명으로 옳지 않은 것은?', '["식별자 관계는 부모로부터 받은 식별자를 자식의 주식별자로 사용한다","비식별자 관계는 부모로부터 받은 속성을 자식의 일반 속성으로 사용한다","IE 표기법에서 식별자 관계는 실선, 비식별자 관계는 점선으로 표시한다","식별자 관계인 부모-자식 관계는 항상 1:1 관계가 된다"]'::jsonb, 3, '"식별자 관계는 1:1 또는 1:M 모두 가능. 부모 PK 만으로 자식 PK 구성 시 1:1, 다른 속성과 합쳐 PK 구성 시 1:M."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-1-cp-10', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', null, 1, 3, '다음 중 키와 무결성의 짝으로 옳지 않은 것은?', '["기본키 (PK) — 개체 무결성","외래키 (FK) — 참조 무결성","CHECK 제약 — 도메인 무결성","외래키 (FK) — 내부식별자"]'::jsonb, 3, '"외래키는 다른 테이블의 PK 를 참조하므로 외부식별자입니다. 내부식별자는 엔터티 내부에서 스스로 생성되는 식별자."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-2-cp-01', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', null, 1, 2, '다음 중 이상 현상(Anomaly)이 아닌 것은?', '["삽입 이상","삭제 이상","갱신 이상","조회 이상"]'::jsonb, 3, '"이상 현상 3종은 삽입·삭제·갱신 이상 (\"삽삭갱\"). 조회는 부작용이 없습니다."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-2-cp-02', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', null, 1, 3, '함수적 종속에 대한 설명으로 옳지 않은 것은?', '["A 속성에 의해 B가 유일하게 결정되면 A → B 라 한다","결정자는 A, 종속자는 B 이다","완전 함수적 종속은 종속자가 기본키의 일부에만 종속되는 경우다","부분 함수적 종속을 제거하면 제2정규형이 된다"]'::jsonb, 2, '"완전 함수적 종속은 기본키 \"전체\"에 종속. 일부에만 종속되는 것은 부분 함수적 종속이며, 이를 제거하면 2NF."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-2-cp-03', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', null, 1, 3, '"기본키 전체에 대해 완전 함수적 종속을 만족"하는 정규형은?', '["제1정규형","제2정규형","제3정규형","BCNF"]'::jsonb, 1, '"1NF=원자값, 2NF=부분 함수 종속 제거(완전 함수 종속), 3NF=이행 함수 종속 제거, BCNF=결정자=후보키 (\"도부이결\")."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-2-cp-04', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', null, 1, 2, '반정규화(Denormalization)를 고려하기 가장 적절한 상황은?', '["INSERT/UPDATE 성능 향상이 필요할 때","조회 시 대량의 JOIN 으로 응답이 느릴 때","저장 공간을 최소화해야 할 때","데이터 일관성이 최우선 요구사항일 때"]'::jsonb, 1, '"반정규화는 조회 성능 향상이 목적입니다. 컬럼 중복·테이블 통합·파생 컬럼·요약 테이블 등으로 JOIN 횟수를 줄입니다. 갱신 부담↑·일관성 리스크↑."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-2-cp-05', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', null, 1, 2, '계층형 데이터 모델에 대한 설명으로 옳은 것은?', '["두 개의 다른 테이블을 1:M 으로 연결한 모델","같은 테이블을 자기 참조 — 셀프 조인·계층형 질의로 처리","관계형 DB 에서는 표현할 수 없는 모델","엔터티 간의 개체 무결성을 자동 보장한다"]'::jsonb, 1, '"계층형 모델 (예: 사원-상사) 은 같은 테이블이 자기 자신을 참조하는 구조. 셀프 조인 또는 CONNECT BY 같은 계층형 질의로 다룹니다."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-2-cp-06', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', null, 1, 2, '트랜잭션이 동시에 실행될 때 다른 트랜잭션의 영향을 받지 않고 독립적으로 실행되어야 하는 ACID 특성은?', '["원자성(Atomicity)","일관성(Consistency)","고립성(Isolation)","지속성(Durability)"]'::jsonb, 2, '"고립성(Isolation) — 동시에 실행되는 트랜잭션이 서로 간섭하지 않음. 격리 수준(Read Uncommitted ~ Serializable) 으로 강도 조정."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-2-cp-07', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', null, 1, 3, 'NULL 에 대한 설명으로 옳은 것은?', '["NULL 은 0과 같은 의미다","집계함수 중 SUM/AVG 는 NULL 을 무시하지만 COUNT(*) 는 NULL 도 포함한다","NULL = NULL 은 TRUE 이다","Oracle 에서 ORDER BY ASC 시 NULL 은 가장 앞에 위치한다"]'::jsonb, 1, '"COUNT(*) 는 모든 행 — NULL 포함. SUM/AVG/MIN/MAX/COUNT(컬럼) 은 NULL 무시. NULL = NULL 은 UNKNOWN. Oracle ASC 시 NULL 은 끝(NULLS LAST)."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-1-2-cp-08', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', null, 1, 2, '인조식별자(Surrogate Key)의 특징으로 옳지 않은 것은?', '["비즈니스 의미와 무관하게 인위적으로 생성된 식별자다","유지보수가 용이하고 변경 리스크가 적다","주민번호나 사업자번호처럼 업무에 이미 존재하는 값을 활용한다","데이터 중복 가능성과 불필요한 인덱스 부담이 단점이다"]'::jsonb, 2, '"인조식별자는 인위적 생성 (일련번호·UUID). 주민번호 등 업무에 이미 존재하는 값을 사용하는 것은 본질식별자입니다."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-01', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 1, '다음 중 SQL 명령어와 그룹의 짝으로 옳지 않은 것은?', '["DDL — TRUNCATE","DML — DROP","DCL — REVOKE","TCL — COMMIT"]'::jsonb, 1, '"DROP 은 DDL 입니다. DML 은 SELECT/INSERT/UPDATE/DELETE/MERGE. TRUNCATE 도 DDL 이므로 자동 COMMIT 됩니다."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-02', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 1, '관계대수 연산자 중 "두 릴레이션에 모두 존재하는 튜플만 추출" 하는 연산은?', '["σ (Selection)","∪ (Union)","∩ (Intersect)","× (Cartesian)"]'::jsonb, 2, '"∩ Intersect — 교집합. σ 는 조건 만족 행 선택, ∪ 는 합집합, × 는 모든 조합 (카티시안 곱)."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-03', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 2, 'SQL 절들의 논리적 처리 순서로 올바른 것은?', '["SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY","FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY","FROM → SELECT → WHERE → GROUP BY → HAVING → ORDER BY","WHERE → FROM → HAVING → GROUP BY → SELECT → ORDER BY"]'::jsonb, 1, '"FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY (\"프웨그하셀오\"). SELECT 가 5번째라 ALIAS 는 ORDER BY 에서만 사용 가능."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-04', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 2, 'ALIAS(별칭) 사용에 관한 설명으로 옳지 않은 것은?', '["AS 키워드는 생략 가능하다","FROM 절의 테이블에도 별칭을 부여할 수 있다","SELECT 에서 정의한 별칭을 같은 쿼리의 WHERE 절에서 사용할 수 있다","별칭에 공백이나 특수문자를 포함하려면 큰따옴표(\"...\")로 감싼다"]'::jsonb, 2, '"WHERE 절은 SELECT 보다 먼저 실행되므로 SELECT 의 별칭을 사용할 수 없습니다. ORDER BY 에서는 가능 (실행 순서상 SELECT 뒤)."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-05', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 3, '다음 SUBSTR 함수 실행 결과 중 다른 결과가 나오는 것은? (Oracle 기준)', '["SUBSTR(''abcdefgh'', 7)","SUBSTR(''abcdefgh'', -2)","SUBSTR(''abcdefgh'', 8, -2)","SUBSTR(''abcdefgh'', INSTR(''abcdefgh'',''g''), 2)"]'::jsonb, 2, '"(1) 7번째부터 끝까지 = ''gh''. (2) 뒤에서 2번째부터 끝 = ''gh''. (4) INSTR=7 이므로 SUBSTR(s,7,2) = ''gh''. (3) 길이가 음수(-2) → Oracle 은 NULL 반환."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-06', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 2, '다음 함수 실행 결과로 옳은 것은?

ROUND(15.58, -1)
TRUNC(15.58, 1)
CEIL(3.58)', '["10, 15.6, 3","20, 15.5, 4","16, 15.5, 4","20, 15.6, 3"]'::jsonb, 1, '"ROUND(15.58, -1) = 20 (10의 자리에서 반올림). TRUNC(15.58, 1) = 15.5 (소수 1자리 아래 버림). CEIL(3.58) = 4."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-07', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 3, '다음 쿼리의 결과값은?

SELECT NVL(COUNT(*), 9999) FROM TABLE WHERE 1=2;', '["NULL","1","9999","0"]'::jsonb, 3, '"WHERE 1=2 로 어떤 행도 만족하지 않지만 COUNT(*) 는 0을 반환합니다 (NULL 아님). 따라서 NVL(0, 9999) = 0. SUM/AVG 는 NULL 이라 NVL 이 적용됩니다."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-08', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 2, '다음 중 결과가 다른 것은? (col 이 NULL 이면 -1, 아니면 0 반환)', '["CASE col WHEN NULL THEN -1 ELSE 0 END","CASE WHEN col IS NULL THEN -1 ELSE 0 END","DECODE(col, NULL, -1, 0)","NVL2(col, 0, -1)"]'::jsonb, 0, '"Simple CASE 의 \"WHEN NULL\" 은 = NULL 비교라 항상 UNKNOWN → ELSE 적중. NULL 분기는 Searched CASE (IS NULL) 또는 DECODE 사용. NVL2(col, x, y) 는 NOT NULL=x, NULL=y."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-09', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 2, '다음 중 NULL 처리에 대한 설명으로 옳은 것은?', '["DECODE 는 NULL 비교에 사용할 수 없다","CASE 표현식의 Simple CASE 형태는 NULL 분기를 정상 처리한다","COALESCE(a, b, c) 는 인자 중 첫 NOT NULL 값을 반환한다","NULLIF(a, b) 는 a 와 b 가 같으면 b 를 반환한다"]'::jsonb, 2, '"COALESCE 는 왼쪽부터 첫 NOT NULL 반환. NULLIF(a,b) 는 a=b 면 NULL, 다르면 a. DECODE 는 NULL 비교 가능 (Oracle 전용 특성). Simple CASE 의 WHEN NULL 은 동작 X."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-10', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 2, '다음 LIKE 절 중 "K" 또는 "T" 로 시작하고 "im" 으로 끝나는 3글자 이름을 찾는 것은? (SQL Server)', '["WHERE name LIKE ''_im''","WHERE name LIKE ''%im''","WHERE name LIKE ''KT_im''","WHERE name LIKE ''[KT]im''"]'::jsonb, 3, '"SQL Server 의 [KT] 는 K 또는 T 한 글자 매칭. ''%im'' 은 길이 무관 모두, ''_im'' 은 임의 한 글자 + im (3글자). 정확히 K나 T로 시작하는 3글자 이름은 [KT]im."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-11', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 2, '"부서별 평균 급여가 500만원 이상인 부서만 조회" 하려 할 때 옳은 쿼리는?', '["SELECT 부서, AVG(급여) FROM EMP WHERE AVG(급여) >= 5000000 GROUP BY 부서","SELECT 부서, AVG(급여) FROM EMP GROUP BY 부서 WHERE AVG(급여) >= 5000000","SELECT 부서, AVG(급여) FROM EMP GROUP BY 부서 HAVING AVG(급여) >= 5000000","SELECT 부서, AVG(급여) FROM EMP HAVING AVG(급여) >= 5000000 GROUP BY 부서"]'::jsonb, 2, '"WHERE 는 행 단위 — 집계함수 사용 불가. 집계 결과 조건은 HAVING. 절 순서는 GROUP BY → HAVING → ORDER BY."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-1-cp-12', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', null, 1, 2, 'ORDER BY 와 NULL 정렬에 대한 설명으로 옳지 않은 것은?', '["ORDER BY 의 기본 정렬 방향은 ASC 이며 생략 가능하다","Oracle 은 ASC 시 NULL 을 마지막에, DESC 시 NULL 을 처음에 둔다","SQL Server 는 ASC 시 NULL 을 처음에 둔다","ORDER BY 절에서는 SELECT 의 별칭(ALIAS)을 사용할 수 없다"]'::jsonb, 3, '"ORDER BY 는 SELECT 뒤에 실행되므로 별칭·컬럼번호·집계함수 모두 사용 가능합니다. NULL 정렬은 Oracle 과 SQL Server 가 반대."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-01', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 2, '양쪽 테이블의 모든 행을 보존하며, 매칭되지 않는 쪽은 NULL 로 채우는 JOIN 은?', '["INNER JOIN","LEFT OUTER JOIN","FULL OUTER JOIN","CROSS JOIN"]'::jsonb, 2, '"FULL OUTER JOIN — 양쪽 테이블의 모든 행을 보존하고 매칭이 없는 쪽은 NULL. INNER 는 매칭만, LEFT/RIGHT 는 한 쪽만 보존, CROSS 는 모든 쌍."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-02', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 2, 'JOIN 표기에 대한 설명으로 옳지 않은 것은?', '["USING(컬럼) 은 양쪽 테이블에 같은 이름의 컬럼이 있을 때 사용한다","ON 절은 컬럼명이 달라도 사용 가능하며 가장 명시적이다","NATURAL JOIN 은 ON / USING 절 없이 같은 이름 컬럼을 자동 매칭한다","INNER JOIN B ON (DEPT_ID) 와 같이 단일 컬럼명만으로 ON 절을 작성할 수 있다"]'::jsonb, 3, '"ON 절은 표현식이 와야 하므로 단일 컬럼명만으로는 오류. ON A.dept_id = B.dept_id 같이 표현식이 필요. USING 은 단일 컬럼명 가능."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-03', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 2, '5행 × 4행 두 테이블을 CROSS JOIN 하면 결과 행 수는?', '["9","5","20","1"]'::jsonb, 2, '"CROSS JOIN = 카티시안 곱 = M × N = 5 × 4 = 20행. 매칭 조건이 없어 모든 가능한 쌍이 생성됩니다."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-04', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 3, '서브쿼리 유형에 대한 설명으로 옳은 것은?', '["스칼라 서브쿼리 — FROM 절에서 임시 테이블처럼 사용","인라인 뷰 — SELECT 절에서 한 행·한 컬럼 반환","다중행 서브쿼리 — IN, ANY, ALL, EXISTS 와 함께 사용","상호연관 서브쿼리 — 바깥 쿼리 값을 참조하지 않는 독립 쿼리"]'::jsonb, 2, '"다중행 서브쿼리는 여러 행을 반환하므로 IN/ANY/ALL/EXISTS 와 사용. 스칼라는 SELECT 절·1행1컬럼, 인라인 뷰는 FROM 절. 상호연관은 바깥을 참조 → 행마다 실행."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-05', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 3, '다음 중 "계약이 한 번도 없는 회원" 을 찾는 가장 안전한 SQL 은?
(계약 테이블에 NULL 회원ID 가 섞여 있을 가능성 있음)', '["SELECT * FROM 회원 WHERE 회원ID NOT IN (SELECT 회원ID FROM 계약)","SELECT * FROM 회원 M WHERE NOT EXISTS (SELECT 1 FROM 계약 C WHERE C.회원ID = M.회원ID)","SELECT * FROM 회원 LEFT JOIN 계약 USING(회원ID) WHERE 1=1","SELECT * FROM 회원 INTERSECT SELECT * FROM 계약"]'::jsonb, 1, '"NOT IN 의 서브쿼리 결과에 NULL 이 섞이면 모두 UNKNOWN → 0행 반환. NOT EXISTS 는 NULL 영향 없음. LEFT JOIN + IS NULL 패턴도 안전."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-06', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 2, 'INTERSECT 에 대한 설명으로 가장 적절한 것은?', '["여러 쿼리 결과의 합집합으로 중복된 행은 하나로 출력한다","여러 쿼리 결과의 합집합으로 중복된 행도 그대로 출력한다","여러 쿼리 결과의 교집합으로 중복된 행은 하나로 출력한다","쿼리 결과 간의 차집합으로 중복된 행은 하나로 출력한다"]'::jsonb, 2, '"INTERSECT — 교집합 + 중복 제거. 합집합 중복 제거는 UNION, 합집합 중복 포함은 UNION ALL, 차집합은 MINUS/EXCEPT."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-07', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 3, 'ROLLUP 과 CUBE 에 대한 설명으로 옳지 않은 것은?', '["ROLLUP(a, b) 은 (a,b), (a), () 를 생성한다","CUBE(a, b) 은 (a,b), (a), (b), () 를 생성한다","ROLLUP 은 컬럼 순서가 바뀌어도 결과가 동일하다","GROUPING SETS 는 원하는 그룹 조합을 직접 명시할 수 있다"]'::jsonb, 2, '"ROLLUP 은 컬럼 순서에 따라 결과가 달라집니다 (소계가 어느 컬럼 기준인지 변함). CUBE 는 모든 부분집합을 만들므로 순서 무관."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-08', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 2, '급여가 4000, 4000, 3000, 3000, 2000 일 때 ORDER BY 급여 ASC 기준 ROW_NUMBER, RANK, DENSE_RANK 의 첫 행(2000) 다음 행(3000) 결과로 옳은 것은?', '["ROW_NUMBER=1, RANK=1, DENSE_RANK=1 (모두 첫 행과 같음)","ROW_NUMBER=2, RANK=2, DENSE_RANK=2","ROW_NUMBER=2, RANK=2, DENSE_RANK=2 (첫 행이 2000=1, 다음 3000=2)","ROW_NUMBER=3, RANK=3, DENSE_RANK=2"]'::jsonb, 2, '"ROW_NUMBER 는 동률 없이 순번 (1,2,3,4,5). RANK 는 동률 같은 순위 + 다음 건너뜀 (1,2,2,4,4 또는 ASC 기준 첫 2000=1). DENSE_RANK 는 건너뛰지 않음. 2000(1) 다음 3000 은 DENSE_RANK=2."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-09', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 3, '윈도우 함수와 GROUP BY 의 차이로 옳은 것은?', '["윈도우 함수는 행 수를 줄이지만 GROUP BY 는 유지한다","GROUP BY 는 행 수를 줄이지만 윈도우 함수는 모든 행을 유지한다","둘 다 행 수를 줄이지 않는다","둘 다 행 수를 같은 방식으로 줄인다"]'::jsonb, 1, '"GROUP BY 는 그룹당 한 행으로 압축, 윈도우 함수는 OVER() 로 그룹 계산을 행마다 표시 — 원본 행 수 유지. \"각 행 옆에 그룹 평균 표시\" 같은 요구는 윈도우만 가능."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-10', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 3, 'ROWS 와 RANGE 의 차이로 옳은 것은?', '["ROWS 는 값 단위, RANGE 는 행 단위로 윈도우를 정의한다","ROWS 는 행 단위, RANGE 는 값 단위로 윈도우를 정의한다","둘은 동의어이며 결과가 항상 같다","ROWS 는 Oracle 전용, RANGE 는 SQL Server 전용이다"]'::jsonb, 1, '"ROWS — 행 개수 단위 (같은 값이라도 한 행씩). RANGE — 정렬 키 값 단위 (같은 값은 묶어서 처리). 누적 합·이동 평균에서 차이가 명확합니다."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-11', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 3, '다음 중 Oracle 에서 "매출 상위 5건 (TOP 5)" 조회 방법으로 옳지 않은 것은?', '["SELECT * FROM 판매 ORDER BY 매출 DESC FETCH FIRST 5 ROWS ONLY","SELECT * FROM (SELECT * FROM 판매 ORDER BY 매출 DESC) WHERE ROWNUM <= 5","SELECT TOP 5 * FROM 판매 ORDER BY 매출 DESC","SELECT * FROM 판매 ORDER BY 매출 DESC OFFSET 0 ROWS FETCH NEXT 5 ROWS ONLY"]'::jsonb, 2, '"TOP 은 SQL Server 전용입니다. Oracle 은 ROWNUM(인라인뷰 + 정렬) 또는 12c+ 의 FETCH FIRST 사용. ROWNUM 을 외부에서 ORDER BY 와 직접 결합하면 정렬 전 번호라 잘못된 결과."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-2-cp-12', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', null, 1, 2, '정규표현식 기호에 대한 설명으로 옳은 것은?', '["? — 대상이 0회 또는 1회 출현","* — 대상이 1회 이상 반복","+ — 대상이 0회 이상 반복","{m,} — 대상이 0회 이상 반복"]'::jsonb, 0, '"? = 0 또는 1회. * = 0회 이상. + = 1회 이상. {m,} = m 회 이상. {n,m} = n~m 회."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-3-cp-01', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', null, 1, 2, '다음 INSERT 문 중 오류가 발생하는 것은?

CREATE TABLE TBL (
  ID NUMBER PRIMARY KEY,
  AMT NUMBER NOT NULL,
  DEGREE VARCHAR2(1)
);', '["INSERT INTO TBL VALUES(1, 100, ''A'')","INSERT INTO TBL(ID, AMT) VALUES(2, 200)","INSERT INTO TBL(ID, DEGREE) VALUES(3, ''X'')","INSERT INTO TBL VALUES(4, 400, NULL)"]'::jsonb, 2, '"(3) 은 NOT NULL 인 AMT 컬럼을 명시하지 않았으므로 NULL 이 들어가 제약 위반. (1)(2)(4) 는 모두 정상. (1) 은 모든 컬럼 순서대로 입력."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-3-cp-02', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', null, 1, 2, 'MERGE 문에 대한 설명으로 옳지 않은 것은?', '["MERGE INTO 대상 USING 소스 ON (조건) 형태로 작성한다","WHEN MATCHED THEN 절은 ON 조건이 참인 행에 대해 수행된다","WHEN NOT MATCHED THEN 절은 일반적으로 INSERT 를 수행한다","MERGE 는 항상 두 작업을 별도 트랜잭션으로 실행한다"]'::jsonb, 3, '"MERGE 의 INSERT/UPDATE 는 단일 SQL 로 한 트랜잭션 내에서 실행됩니다. ETL·증분 동기화에 자주 사용."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-3-cp-03', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', null, 1, 3, '다음 SQL 실행 후 SELECT COUNT(*) FROM T 의 결과는?

INSERT INTO T VALUES(1);
INSERT INTO T VALUES(2);
INSERT INTO T VALUES(3);
SAVEPOINT SV1;
INSERT INTO T VALUES(4);
INSERT INTO T VALUES(5);
COMMIT;
INSERT INTO T VALUES(6);
ROLLBACK TO SAVEPOINT SV1;', '["3","5","6","오류 발생"]'::jsonb, 3, '"COMMIT 후에는 SAVEPOINT 가 모두 사라지므로 ROLLBACK TO SV1 은 \"존재하지 않는 SAVEPOINT\" 오류. COMMIT 직전까지 5건이 영구 반영, 그 뒤 INSERT 6은 별도 트랜잭션. SV1 ROLLBACK 자체가 실패하므로 6번도 그대로 유지되어 6건."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-3-cp-04', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', null, 1, 2, 'AUTOCOMMIT 동작에 관한 설명으로 옳지 않은 것은?', '["Oracle 의 DDL 은 항상 자동 COMMIT 된다","Oracle 의 DML 은 기본적으로 AUTOCOMMIT 이 OFF 라 명시적 COMMIT 이 필요하다","SQL Server 는 기본적으로 AUTOCOMMIT 이 ON 으로 동작한다","DDL 실행 후에도 직전 DML 은 ROLLBACK 으로 되돌릴 수 있다"]'::jsonb, 3, '"Oracle 에서 DDL 실행 시 직전 DML 까지 함께 자동 COMMIT 됩니다. 따라서 DDL 후엔 그 이전 DML 도 ROLLBACK 불가."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-3-cp-05', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', null, 1, 2, '다음 중 테이블/컬럼 명명 규칙으로 옳지 않은 것은?', '["숫자로 시작할 수 없다","예약어를 사용할 수 없다","같은 테이블 내에 동일한 이름의 컬럼을 여러 개 만들 수 있다","Oracle 에서 길이는 일반적으로 30자 이내로 제한된다"]'::jsonb, 2, '"동일 테이블에 같은 이름 컬럼은 만들 수 없습니다 (식별 불가). 숫자로 시작 X, 예약어 X, 길이 제한은 모두 옳음."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-3-cp-06', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', null, 1, 2, 'DELETE / TRUNCATE / DROP 비교로 옳지 않은 것은?', '["DELETE 는 WHERE 조건으로 일부 행만 삭제 가능하며 ROLLBACK 가능","TRUNCATE 는 모든 행을 삭제하지만 테이블 구조는 유지한다","DROP 은 테이블의 데이터와 구조 모두 삭제한다","DELETE 는 DDL 이라 자동 COMMIT 된다"]'::jsonb, 3, '"DELETE 는 DML — ROLLBACK 가능, 자동 COMMIT 아님. TRUNCATE 와 DROP 이 DDL 로 자동 COMMIT."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-3-cp-07', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', null, 1, 2, '제약조건에 관한 설명으로 옳지 않은 것은?', '["PRIMARY KEY 는 테이블당 1개만 둘 수 있다 (복합 컬럼 가능)","UNIQUE 제약은 NULL 을 허용한다","FOREIGN KEY 는 참조 테이블의 PK 를 참조해 참조 무결성을 보장한다","기존 데이터에 NULL 이 있어도 NOT NULL 제약을 추가할 수 있다"]'::jsonb, 3, '"기존에 NULL 값이 있는 컬럼에 NOT NULL 을 추가하면 제약 위반으로 오류. 먼저 NULL 을 채운 뒤 추가해야 합니다."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-2-3-cp-08', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', null, 1, 3, 'WITH GRANT OPTION 과 WITH ADMIN OPTION 의 차이로 옳지 않은 것은?', '["WITH GRANT OPTION 은 객체 권한(SELECT 등) 부여 시 사용한다","WITH ADMIN OPTION 은 시스템 권한(CREATE TABLE 등) 부여 시 사용한다","WITH GRANT OPTION 으로 부여된 권한은 회수 시 연쇄 회수된다","WITH ADMIN OPTION 으로 부여된 권한도 회수 시 연쇄 회수된다"]'::jsonb, 3, '"WITH ADMIN OPTION 은 회수해도 받은 사용자의 권한은 유지됩니다. WITH GRANT OPTION 만 연쇄 회수됨."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/concept-practice.json', now()),
  ('sqld-54-1', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '모델링 단계', 1, 2, '다음 설명에 가장 적절한 것은?

[설명] 시스템으로 구축하고자 하는 업무에 대해 Key, 속성, 관계 등을 정확하게 표현하고 재사용성이 높은 모델링', '["논리적 데이터 모델링","개념적 데이터 모델링","물리적 데이터 모델링","데이터베이스 모델링"]'::jsonb, 0, '"논리적 모델링은 정규화·키·관계·재사용성이 핵심 특징. 개념적은 추상도 ↑·전체 그림, 물리적은 DBMS 종속·인덱스·스토리지."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-54.json', now()),
  ('sqld-54-2', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '엔터티 특징', 1, 2, '엔터티의 특징으로 적절하지 않은 것은?', '["엔터티는 고유한 식별자를 가진다","엔터티는 데이터 저장의 기본 단위이다","엔터티는 반드시 속성을 가진다","속성이 없는 엔터티가 존재할 수 있다"]'::jsonb, 3, '"엔터티 5요건 중 \"속성을 반드시 가짐\" 이 포함됩니다. 속성이 없는 엔터티는 의미가 없어 모델링 대상이 아님."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-54.json', now()),
  ('sqld-54-3', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '속성 — 파생 속성', 1, 2, '속성에 관한 설명으로 적절하지 않은 것은?', '["속성은 엔터티의 특성을 나타낸다","속성에는 기본 속성과 파생 속성이 있다","파생 속성은 다른 속성에서 계산된다","파생 속성은 많을수록 좋다"]'::jsonb, 3, '"파생 속성이 많을수록 원본 변경 시 일관성 유지 비용 ↑. 꼭 필요한 곳만 사용 권장."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-54.json', now()),
  ('sqld-54-4', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '주식별자 불변성', 1, 2, '식별자의 특징으로 적절하지 않은 것은?', '["식별자는 엔터티의 유일성을 보장한다","식별자는 최소성 조건을 만족해야 한다","주식별자는 엔터티를 고유하게 식별한다","주식별자의 값은 자주 변할 수 있다"]'::jsonb, 3, '"주식별자 4요건 — 유일·최소·불변·존재. 불변성 = 자주 변하지 않아야 함."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-54.json', now()),
  ('sqld-54-5', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '비식별자 관계', 1, 3, '식별자/비식별자 관계에 관한 설명으로 적절하지 않은 것은?', '["식별자 관계는 부모와 종속적인 강한 관계를 맺는다","비식별자 관계에서 부모와의 관계 참여는 필수 조건이다","식별자 관계는 부모의 식별자를 자식에게 전달한다","비식별자 관계는 자식 엔터티가 독립적으로 존재할 수 있다"]'::jsonb, 1, '"비식별자 관계는 약한 관계로 부모쪽 참여가 [선택적] 일 수 있습니다. \"필수\" 가 함정."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-54.json', now()),
  ('sqld-54-6', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', 'FK 식별자 상속', 1, 2, '고객-주문 ERD 에서 "주문" 의 "고객번호" 컬럼에 대해 옳은 설명은?', '["고객 엔터티에서 상속받은 외래키","주문 엔터티 내부에서 새로 만든 식별자","고객의 주식별자가 아닌 일반 속성","주문의 주식별자"]'::jsonb, 0, '"\"고객번호\" 는 고객 PK 를 주문이 외래키로 받아온 것 — 외부식별자(FK) 이며 식별자 상속의 결과."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-54.json', now()),
  ('sqld-54-7', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', '함수 종속/2NF', 1, 3, '함수 종속성에 관한 설명으로 옳은 것은?', '["일반 속성이 주식별자 모두에 함수 종속성이 있는 상태는 제3정규형 만족","일반 속성이 주식별자 모두에 함수 종속성이 있는 상태는 제2정규형 만족","상품번호가 상품명에 종속된다","상품명이 결정자, 상품번호가 종속자다"]'::jsonb, 1, '"주식별자 \"전체\" 에 종속 = 완전 함수 종속 = 2NF. 상품번호 → 상품명 (역방향 X)."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-54.json', now()),
