) values
  ('sqld-55-41', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', 'VIEW', 1, 2, '뷰(View)에 대한 설명으로 옳지 않은 것은?', '["실제 데이터를 디스크에 저장하지 않으며 논리적으로 생성된 객체이다","보안성 — 전체 데이터를 노출하지 않고 일부만 공개 가능","독립성 — 기반 테이블 구조 변경 시 응용 프로그램 영향 최소화","조회 속도를 항상 본 테이블보다 빠르게 한다"]'::jsonb, 3, '"뷰는 가상 테이블 — 매 실행 시 정의된 SELECT 가 실행되므로 일반적으로 본 테이블 조회와 비슷하거나 약간 느립니다. 보안·편의성·독립성을 위한 도구."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-55.json', now()),
  ('sqld-55-42', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', 'CTAS', 1, 3, 'CTAS (CREATE TABLE AS SELECT)로 테이블을 복제할 때 자동으로 함께 복사되는 제약조건은?', '["기본키(PK)","외래키(FK)","NOT NULL 제약","CHECK 제약 + DEFAULT"]'::jsonb, 2, '"CTAS 는 데이터 + 컬럼 정의 + NOT NULL 만 자동 복제됩니다. PK·FK·UNIQUE·CHECK·DEFAULT 등은 별도로 ALTER 로 추가해야 함."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-55.json', now()),
  ('sqld-55-43', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', '트랜잭션 격리수준', 1, 3, 'Repeatable Read 격리 수준에서 발생하는 부작용은?', '["Dirty Read","Non-Repeatable Read","Phantom Read","어떤 부작용도 발생 X"]'::jsonb, 2, '"Read Uncommitted < Read Committed < Repeatable Read < Serializable. Repeatable Read 까지 차단된 것은 Dirty + NonRepeatable. Phantom Read 만 남음. Serializable 에서 Phantom 도 차단."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-55.json', now()),
  ('sqld-55-44', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'DECODE', 1, 3, 'Oracle 의 DECODE 함수에 대한 설명으로 옳은 것은?', '["DECODE 는 표준 SQL 의 함수이며 모든 DBMS 에서 동일하게 동작한다","DECODE 는 NULL 을 다른 값과 같다고 비교할 수 있다 (Simple CASE 와 차이)","DECODE 의 결과 타입은 항상 첫 번째 인수의 타입을 따른다","DECODE 는 WHERE 절에서만 사용 가능하다"]'::jsonb, 1, '"DECODE 는 Oracle 전용. NULL 비교 시 NULL == NULL 을 TRUE 로 처리(Simple CASE 의 WHEN NULL 함정과 다름). 결과 타입은 두 번째 이후 인자 타입."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-55.json', now()),
  ('sqld-55-45', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', '단일행 함수', 1, 2, '단일행 함수에 대한 설명으로 옳지 않은 것은?', '["각 행에 개별적으로 적용된다","여러 인자를 받을 수 있다","함수의 인자로 함수를 사용하는 중첩 사용이 가능하다","GROUP BY 절에서는 사용할 수 없다"]'::jsonb, 3, '"단일행 함수는 SELECT, WHERE, ORDER BY, GROUP BY 절 모두에서 사용 가능합니다. 행 단위로 작동하므로 그룹화 키로도 사용 가능."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-55.json', now()),
  ('sqld-55-46', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', 'INNER JOIN', 1, 2, 'INNER JOIN 에 대한 설명으로 옳지 않은 것은?', '["양쪽에 매칭되는 행만 결과로 반환한다","JOIN 키 컬럼명은 양쪽 테이블에서 같지 않아도 된다 (ON 절 사용 시)","JOIN 만 단독으로 사용하면 INNER JOIN 을 의미한다","조인하는 두 컬럼은 반드시 컬럼명이 같아야 한다"]'::jsonb, 3, '"ON 절을 쓰면 컬럼명이 달라도 JOIN 가능 (예: ON A.dept_id = B.id). USING 이나 NATURAL 만 같은 이름 요구."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-55.json', now()),
  ('sqld-55-47', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', 'ROWNUM', 1, 3, 'Oracle 의 ROWNUM 에 대한 설명으로 옳지 않은 것은?', '["쿼리 결과에 순차 번호를 부여하는 가상 컬럼이다","WHERE ROWNUM = 1 은 사용 가능하다","WHERE ROWNUM = 5 는 정상적으로 5번째 행을 반환한다","1보다 큰 숫자에 대한 = 비교는 0 행을 반환한다"]'::jsonb, 2, '"ROWNUM 은 행이 \"통과한 후\" 부여되므로 처음부터 순차로만 부여 가능. ROWNUM = 1 은 첫 행을 통과시켜 부여 가능, ROWNUM = 5 는 \"앞 4개를 통과 안 했는데 5가 어떻게 나오나\" → 0행."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-55.json', now()),
  ('sqld-55-48', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '무결성', 1, 2, '다음 무결성 짝짓기 중 옳지 않은 것은?', '["PK — 개체 무결성","FK — 참조 무결성","CHECK — 도메인 무결성","도메인 — 사용자 정의 무결성"]'::jsonb, 3, '"도메인은 \"속성이 가질 수 있는 값의 범위\" 정의. 무결성 종류는 개체(PK)·참조(FK)·도메인(CHECK)·사용자 정의 (애플리케이션 레벨) 4가지. 도메인 자체가 사용자 정의 무결성은 아님."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-55.json', now()),
  ('sqld-55-49', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'IN 서브쿼리', 1, 3, '다음 SQL 의 IN 절에 대한 설명으로 옳지 않은 것은?

SELECT * FROM 회원
WHERE 부서ID IN (SELECT 부서ID FROM 부서
                  WHERE 부서장명 IN (''JOHN'',''SMITH''));', '["외부 쿼리는 부서장이 JOHN 또는 SMITH 인 부서에 속한 회원을 반환한다","JOHN 이 두 명이라 같은 부서ID 가 두 번 매칭되어도 회원은 중복 반환되지 않는다","IN 은 내부적으로 DISTINCT 처리되어 같은 값은 한 번만 비교한다","JOHN 이 두 명일 경우 단일행 서브쿼리가 아니라 오류가 발생한다"]'::jsonb, 3, '"IN 은 다중행 서브쿼리에 사용 가능 — JOHN 이 두 명이라 부서ID 가 여러 개 나와도 정상 동작. \"오류\" 는 = 비교(단일행 서브쿼리)에서만 발생."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-55.json', now()),
  ('sqld-55-50', 'sqld', 2, 'SQL 기본 및 활용', '관리 구문', '관리 구문', 'TCL', 1, 3, '다음 시나리오 후 SELECT * FROM TABLE50 의 결과 행 수는?

INSERT INTO TABLE50 VALUES(1);
INSERT INTO TABLE50 VALUES(2);
INSERT INTO TABLE50 VALUES(3);
SAVEPOINT SQL1;
INSERT INTO TABLE50 VALUES(4);
INSERT INTO TABLE50 VALUES(5);
COMMIT;
INSERT INTO TABLE50 VALUES(6);
ROLLBACK TO SAVEPOINT SQL1;', '["4건 (1~3 + INSERT 6)","5건 (1~5 그대로)","3건 (1~3 만 남음)","ROLLBACK 오류 + 6건 (1~6)"]'::jsonb, 3, '"COMMIT 직후 모든 SAVEPOINT 가 사라집니다. ROLLBACK TO SAVEPOINT SQL1 은 ''존재하지 않는 SAVEPOINT'' 오류. COMMIT 으로 1~5 영구 반영, 그 뒤 INSERT 6 도 그대로 남아 총 6건."'::jsonb, 'self-reviewed', true, 'src/data/questions/sqld/past-exams/sqld-55.json', now()),
  ('sqld-56-1', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '스키마', 1, 2, 'ANSI/SPARC 3단계 스키마 구조에 속하지 않는 것은?', '["응용 스키마","외부 스키마","개념 스키마","내부 스키마"]'::jsonb, 0, '"3단계 스키마는 외부(사용자별 뷰) · 개념(전체 통합) · 내부(물리 저장)의 3계층입니다. \"응용 스키마\"는 가짜 보기."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
  ('sqld-56-2', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링', 1, 2, '데이터 모델링에 대한 설명으로 옳지 않은 것은?', '["업무에서 사용되는 모든 데이터를 누락 없이 표현해야 한다","현실 세계를 단순화·추상화·명확화하는 작업이다","업무 규칙은 모델에 포함되지 않아도 된다","데이터·프로세스·상관 관점으로 나누어 분석할 수 있다"]'::jsonb, 2, '"데이터 모델은 업무 규칙(business rule)도 명시적으로 표현해야 합니다. 그래야 일관성 있는 시스템 구현이 가능."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
  ('sqld-56-3', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '엔터티 분류', 1, 2, '엔터티의 발생 시점에 따른 분류가 아닌 것은?', '["행위 엔터티","관계 엔터티","중심 엔터티","기본 엔터티"]'::jsonb, 1, '"발생 시점 분류는 기본·중심·행위 (3종). \"관계 엔터티\"는 분류명에 없는 가짜 보기."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
  ('sqld-56-4', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', 'ERD', 1, 2, '고객·상품·주문 ERD 에 대한 설명으로 옳지 않은 것은?', '["고객과 상품은 일반적으로 기본 엔터티이다","주문은 사건 엔터티에 해당한다","주문상품 엔터티는 주문과 상품의 관계에 의해 생성될 수 있다","한 명의 고객은 반드시 하나의 주문만 가질 수 있다"]'::jsonb, 3, '"고객-주문은 1:N 관계가 일반적입니다. 한 고객이 여러 주문을 가질 수 있어야 현실 모델링 가능."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
  ('sqld-56-5', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '속성 분류', 1, 2, '다른 속성을 이용하여 결과를 도출하는 속성은?', '["설계 속성","기본 속성","파생 속성","관계 속성"]'::jsonb, 2, '"파생 속성은 다른 속성에서 계산·가공으로 만들어지는 속성. 합계·평균·나이(생년월일에서 계산) 등."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
  ('sqld-56-6', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '속성 분류', 1, 3, '다음 설명 중 옳은 것을 모두 고른 것은?

(가) 주소는 시·도·도로명·건물번호 등으로 나뉘므로 복합 속성이다
(나) 나이는 단일 속성이다
(다) 주민번호는 단일 값 속성이다
(라) 연락처는 휴대폰·집전화 등 여러 값을 가질 수 있어 다중 값 속성이다', '["가, 라","가, 나, 다","나, 다, 라","가, 나, 다, 라"]'::jsonb, 3, '"분해 가능 여부: 단일·복합·다중값. (가)~(라) 모두 정확한 설명입니다."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
  ('sqld-56-7', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '관계', 1, 3, '병원·의사·수술의 ERD 가 다음과 같을 때 옳지 않은 것은?

[병원] ─ ㄱ ─ [의사] ─ ㄴ ─ [수술]
[병원] ──────── ㄷ ─ [수술]

ㄱ·ㄴ 은 모두 1:N, 의사·수술의 ㄴ 은 선택적 참여', '["ㄷ 은 ㄱ 과 ㄴ 을 합한 것과 의미가 같다","의사가 한 명도 없는 병원이 있을 수 있다","수술을 한 번도 집도하지 않은 의사가 있을 수 있다","어떤 의사도 집도하지 않은 수술이 있을 수 있다"]'::jsonb, 0, '"ㄷ 은 ㄱ + ㄴ (전이 관계) 과 의미가 다를 수 있습니다. 직접 관계와 경유 관계는 카디널리티·선택성이 일치한다는 보장이 없음."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
  ('sqld-56-8', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델링의 이해', '데이터 모델링의 이해', '식별자', 1, 2, '업무 활동에 의해 자연스럽게 만들어진 식별자는?', '["외부식별자","내부식별자","본질식별자","인조식별자"]'::jsonb, 2, '"본질식별자 — 업무에서 본래 존재하는 식별자(주민번호, 사업자번호 등). 인조식별자는 인위적으로 생성한 식별자."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
  ('sqld-56-9', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', '정규화', 1, 3, '"모든 일반 속성이 주식별자에 함수적으로 종속되어 있고 부분 함수 종속이 없다"를 만족하는 정규형은?', '["제1정규형","제2정규형","제3정규형","BCNF"]'::jsonb, 1, '"2NF — 1NF + 부분 함수 종속 제거 (완전 함수적 종속). 3NF 는 2NF + 이행 함수 종속 제거."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
  ('sqld-56-10', 'sqld', 1, '데이터 모델링의 이해', '데이터 모델과 성능', '데이터 모델과 성능', '정규화/반정규화', 1, 2, '정규화·반정규화에 대한 설명으로 옳지 않은 것은?', '["정규화는 이상 현상(Anomaly) 을 방지한다","일반 속성 간의 종속을 제거하는 단계는 제3정규형이다","반정규화는 데이터 중복으로 독립성이 떨어질 수 있다","정규화를 진행할수록 조회 성능은 항상 향상된다"]'::jsonb, 3, '"정규화는 테이블을 늘려 JOIN 횟수가 증가하므로 조회 성능이 떨어질 수 있습니다. 성능이 필요하면 반정규화로 보정."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
  ('sqld-56-11', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', '연산자 우선순위', 1, 1, '다음 연산자 중 우선순위가 가장 높은 것은?', '["비교 연산자","괄호 ( )","AND","OR"]'::jsonb, 1, '"우선순위 (높음 → 낮음): 괄호 → 산술 → 비교 → NOT → AND → OR."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
