  ('sqld-56-13', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 활용', 'SQL 활용', 'JOIN', 1, 2, '다음 JOIN 중 결과 행 수가 다른 하나는? (양쪽에 공통 키가 일부만 있을 때)', '["INNER JOIN","LEFT OUTER JOIN","RIGHT OUTER JOIN","FULL OUTER JOIN"]'::jsonb, 3, '"공통 키만 있는 행이 N 개일 때 INNER, LEFT, RIGHT 는 매칭에 따라 차이가 작지만 FULL OUTER 는 양쪽 비매칭 행을 모두 보존하므로 일반적으로 가장 많은 행을 반환합니다."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
  ('sqld-56-14', 'sqld', 2, 'SQL 기본 및 활용', 'SQL 기본', 'SQL 기본', 'BETWEEN', 1, 2, '다음 중 결과가 다른 하나는? (200 이 COL3 이상 COL4 이하인 행 찾기)', '["WHERE COL3 <= 200 AND COL4 >= 200","WHERE NOT (200 < COL3 OR 200 > COL4)","WHERE 200 BETWEEN COL3 AND COL4","WHERE COL3 >= 200 AND COL4 <= 200"]'::jsonb, 3, '"(4) 는 \"COL3 ≥ 200 그리고 COL4 ≤ 200\" — 의미가 반대 (COL3 가 200 보다 크거나 같고 COL4 가 200 보다 작거나 같으므로 200 이 그 사이가 아니라 그 \"안쪽\")."'::jsonb, 'ai-generated', true, 'src/data/questions/sqld/past-exams/sqld-56.json', now()),
